    "decision_id": {"format": "uuid", "type": "string"},
    "requested_model": {"maxLength": 256, "minLength": 1, "type": "string"},
    "litellm_call_id": {
      "anyOf": [
        {"maxLength": 256, "type": "string"},
        {"type": "null"}
      ],
      "default": null
    },
    "chat_id": {
      "anyOf": [
        {"maxLength": 256, "type": "string"},
        {"type": "null"}
