        {"maxLength": 256, "type": "string"},
        {"type": "null"}
      ],
      "default": null
    },
    "overflow_reason": {
      "anyOf": [
        {"maxLength": 32, "type": "string"},
        {"type": "null"}
      ],
      "default": null
    },
    "finish_reason": {
      "anyOf": [
        {"maxLength": 64, "type": "string"},
        {"type": "null"}
      ],
      "default": null
    },
    "tool_calls": {
      "items": {"type": "string"},
      "maxItems": 256,
      "type": "array"
    },
    "status": {"default": "success", "maxLength": 16, "minLength": 1, "type": "string"},
    "error": {
      "anyOf": [
        {"type": "string"},
        {"type": "null"}
      ],
      "default": null
    }
  },
  "required": ["decision_id"],
  "type": "object",
  "additionalProperties": true
}
```

Response `202` (`application/json`):

```json
